code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    values = [v for row in grid for v in row]
    background = max(set(values), key=values.count)
    components = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            area=(r1-r0+1)*(c1-c0+1)
            if r1>r0 and c1>c0 and len(cells)/area >= 0.75:
                components.append([color,r0,r1,c0,c1,len(cells)==area])
    # A one-cell attached spur can make a perfectly filled rectangle appear one row/column too large.
    # Prefer the repeated extent among separate blocks of the same color in this case.
    for obj in components:
        color,r0,r1,c0,c1,solid=obj
        if not solid: continue
        height=r1-r0+1; width=c1-c0+1
        for other in components:
            if other is obj or other[0] != color: continue
            oh=other[2]-other[1]+1; ow=other[4]-other[3]+1
            if height == oh+1 and width == ow:
                obj[2] -= 1; break
            if width == ow+1 and height == oh:
                obj[4] -= 1; break
    out=[[background]*w for _ in range(h)]
    for color,r0,r1,c0,c1,_ in components:
        if r1-r0+1 >= 2 and c1-c0+1 >= 2:
            for y in range(r0,r1+1):
                for x in range(c0,c1+1): out[y][x]=color
    return out
'''
